MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Pec Deck Machine Fly', 'CHEST', 'SHOULDERS', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Sit on the pec deck machine and adjust the seat so your arms are parallel to the floor.', '["Sit on the pec deck machine and adjust the seat so your arms are parallel to the floor.","Place your forearms against the arm pads or grip the handles with elbows bent at 90 degrees.","Press the arm pads together in front of your chest by contracting your pectoral muscles.","Pause at the peak of the contraction and squeeze your chest.","Slowly allow the arm pads to return to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0051', '/media/exercises/0051.mp4', NULL, 'cc6a9c8d00264497cb69bc5ba80f904e47a9ccd5aab23baae6a4cf9a878a510f', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0051.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Pec Deck (Machine Chest Fly)');
UPDATE exercises SET media_url = '/media/exercises/0051.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Butterfly');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Svend Press Chest', 'CHEST', 'SHOULDERS,TRICEPS', 'BODYWEIGHT', 'BEGINNER', 'COMPOUND', 'Stand upright and hold a pair of weight plates pressed together at chest level with both palms.', '["Stand upright and hold a pair of weight plates pressed together at chest level with both palms.","Press the plates outward from your chest until your arms are nearly fully extended.","Squeeze the plates together throughout the entire movement to engage the inner chest.","Slowly pull the plates back towards your chest in a controlled manner.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0052', '/media/exercises/0052.mp4', NULL, '836a90c8a97978080e712b9e9323f4dcca6da8fc890d5d0ad06280bc349c3054', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0052.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Svend Press');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Air Bike Sprint', 'CARDIO', 'UPPER LEGS,ABS,SHOULDERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the air bike and adjust the seat so your legs are slightly bent at full extension.', '["Sit on the air bike and adjust the seat so your legs are slightly bent at full extension.","Grip the moving handles with both hands.","Begin pedaling and pumping the handles simultaneously at maximum effort.","Sprint at full intensity for the desired interval duration.","Slow down gradually and rest before repeating."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0053', '/media/exercises/0053.mp4', NULL, '0e146ee8d59fbd30dbf335f2f21172d6e39906576139167d6ba1ede0180908c9', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0053.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Air Bike');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Back Squat', 'QUADS', 'GLUTES,UPPER LEGS,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Position a barbell on your upper traps and step back from the rack with feet shoulder-width apart.', '["Position a barbell on your upper traps and step back from the rack with feet shoulder-width apart.","Point your toes slightly outward and keep your chest up and core braced.","Descend by bending your knees and pushing your hips back until your thighs are parallel to the floor.","Drive through your heels to extend your knees and hips and return to the standing position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0054', '/media/exercises/0054.mp4', NULL, '9ff30823cb7ea1189df02378bc16e26d4f151dd8437874b73df6d9320d16265e', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0054.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Barbell Squat');
UPDATE exercises SET media_url = '/media/exercises/0054.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Barbell Full Squat');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Bulgarian Split Squat', 'QUADS', 'GLUTES,UPPER LEGS,LOWER BACK', 'BARBELL', 'ADVANCED', 'COMPOUND', 'Stand in front of a bench and hold a barbell across your upper traps.', '["Stand in front of a bench and hold a barbell across your upper traps.","Extend one leg behind you and rest the top of your foot on the bench.","Lower your back knee toward the floor by bending your front knee, keeping your torso upright.","Descend until your front thigh is parallel to the floor.","Drive through your front heel to return to the starting position and repeat, then switch legs."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0055', '/media/exercises/0055.mp4', NULL, '91c621823dde102dc10f88a57ee241825c9c64836859315215e3aacfa57ca8e2', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0055.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Bulgarian Split Squat');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Front Squat', 'QUADS', 'GLUTES,ABS,UPPER LEGS', 'BARBELL', 'ADVANCED', 'COMPOUND', 'Position a barbell in a front rack across the front of your shoulders with your elbows raised high.', '["Position a barbell in a front rack across the front of your shoulders with your elbows raised high.","Stand with feet shoulder-width apart and toes slightly pointed out.","Keeping your elbows high and torso upright, descend by bending your knees and hips.","Lower until your thighs are parallel to the floor or below.","Drive through your heels to return to the standing position and repeat."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0056', '/media/exercises/0056.mp4', NULL, '61278e6ca7f618638752036ac43f1f4680a86e7167eea0d4c29c9ec1ec79ecce', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0056.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Front Barbell Squat');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Hip Thrust', 'GLUTES', 'UPPER LEGS,LOWER BACK,ABS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on the floor with your upper back against a bench and a padded barbell across your hips.', '["Sit on the floor with your upper back against a bench and a padded barbell across your hips.","Plant your feet flat on the floor hip-width apart with knees bent.","Drive through your heels to thrust your hips upward until your body forms a straight line from knees to shoulders.","Squeeze your glutes at the top of the movement.","Lower your hips back toward the floor in a controlled manner and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0057', '/media/exercises/0057.mp4', NULL, '3af2229f88a752213bdbac4a64247952f2e71858e4c01a6bea9441209052643b', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0057.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Barbell Hip Thrust');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell March', 'QUADS', 'GLUTES,ABS,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Hold a barbell across your upper traps as in a back squat position with feet hip-width apart.', '["Hold a barbell across your upper traps as in a back squat position with feet hip-width apart.","Brace your core and maintain an upright posture.","Lift one knee upward to hip height in a marching motion while keeping your stance foot flat.","Lower your foot and repeat the movement with the opposite leg.","Continue alternating legs in a controlled marching motion for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0058', '/media/exercises/0058.mp4', NULL, 'c10a58cb151f5a5ff78e0ccbd30395ecfbbf6cd6aa66822b6b665284ea3c84f1', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0058.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Barbell March');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Reverse Lunges', 'QUADS', 'GLUTES,UPPER LEGS,ABS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand upright with a barbell across your upper traps and feet together.', '["Stand upright with a barbell across your upper traps and feet together.","Step one foot directly backward and lower your back knee toward the floor.","Continue descending until your front thigh is parallel to the floor.","Push through your front heel to bring your back foot forward to the starting position.","Alternate legs for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0059', '/media/exercises/0059.mp4', NULL, '14fa8529d707fad2996ebd605c7f340d45f97ca5d671cc419e21e6e5f17a5034', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0059.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Barbell Reverse Lunge');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Romanian Deadlift', 'QUADS', 'GLUTES,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with feet hip-width apart holding a barbell in front of your thighs with an overhand grip.', '["Stand with feet hip-width apart holding a barbell in front of your thighs with an overhand grip.","Keep a soft bend in your knees and your back flat throughout the movement.","Hinge at the hips and push them back as you lower the bar along your legs.","Continue lowering until you feel a deep stretch in your hamstrings.","Drive your hips forward to return to the upright position and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0060', '/media/exercises/0060.mp4', NULL, '59946a868d24acea5129f49a3258880dce618b8a90f2f6dd2b536ab967a42c6e', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0060.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Romanian Deadlift');
UPDATE exercises SET media_url = '/media/exercises/0060.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Barbell Romanian Deadlift');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Leg Kickback', 'GLUTES', 'UPPER LEGS,LOWER BACK', 'CABLE', 'BEGINNER', 'COMPOUND', 'Attach an ankle strap to the low pulley of a cable machine and secure it to one ankle.', '["Attach an ankle strap to the low pulley of a cable machine and secure it to one ankle.","Face the machine and hold the frame for support, keeping your body slightly inclined.","Keeping your knee straight, kick your strapped leg backward and upward as far as possible.","Squeeze your glute at the top of the movement.","Slowly return your leg to the starting position and repeat, then switch legs."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0061', '/media/exercises/0061.mp4', NULL, '88013e782dc8a5238ff08394c8c4437612f09bb35f5999d9399818516bb9cc53', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0061.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('One-Legged Cable Kickback');
UPDATE exercises SET media_url = '/media/exercises/0061.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Glute Kickback Machine');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cycling', 'CARDIO', 'UPPER LEGS,LOWER LEGS,GLUTES', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Mount a stationary bike and adjust the seat height so your leg has a slight bend at full pedal extension.', '["Mount a stationary bike and adjust the seat height so your leg has a slight bend at full pedal extension.","Place your feet in the pedal straps and grip the handlebars.","Begin pedaling at a comfortable cadence, maintaining an upright or forward-leaning posture.","Adjust the resistance as needed to reach your target intensity level.","Continue for the desired duration, then gradually slow to a cool down pace."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0062', '/media/exercises/0062.mp4', NULL, '6b34987591120f21f2b69833e0281e293dc75e8587ada90cc124dc1958208d8a', 'licensed', 'video', 'verified', 'vital-catalog');
