MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Jump Squat', 'QUADS', 'GLUTES,UPPER LEGS,LOWER LEGS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with feet shoulder-width apart holding a light dumbbell in each hand at your sides.', '["Stand with feet shoulder-width apart holding a light dumbbell in each hand at your sides.","Perform a squat by bending your knees and pushing your hips back to thigh-parallel depth.","Explosively drive through your heels to jump off the ground as high as possible.","Land softly with bent knees to absorb the impact.","Immediately descend into the next squat and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0066', '/media/exercises/0066.mp4', NULL, '4984907e62eaeca167c41585fa583fdd720fbaece057883c6261f7069a17730e', 'licensed', 'video', 'verified', 'vital-catalog');
