MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hack Squat Machine', 'QUADS', 'GLUTES,UPPER LEGS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Position yourself on the hack squat machine with your back against the pad and shoulders under the shoulder pads.', '["Position yourself on the hack squat machine with your back against the pad and shoulders under the shoulder pads.","Place your feet shoulder-width apart on the platform with toes slightly pointed out.","Release the safety handles and lower the sled by bending your knees to 90 degrees or below.","Drive through your heels to extend your knees and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0068', '/media/exercises/0068.mp4', NULL, '59339ad55ac4e037e4f1987b86c1ee84e8f237a3397fb62c5161a555b953f9b6', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0068.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Hack Squat Machine');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hip Abduction Machine', 'GLUTES', 'UPPER LEGS', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Sit on the hip abduction machine with your outer thighs resting against the padded levers.', '["Sit on the hip abduction machine with your outer thighs resting against the padded levers.","Adjust the starting position so your legs are together and feet are flat on the foot rests.","Push your legs outward against the resistance by abducting your hips as far as comfortable.","Pause at the end of the range of motion, then slowly return your legs to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0069', '/media/exercises/0069.mp4', NULL, 'cecd3a3f65352e1e93154c406c07d7f4f0e5fd05d916d3e8cc8105fc59d1e252', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0069.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Hip Abduction Machine');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Hold March', 'QUADS', 'GLUTES,ABS,LOWER BACK', 'KETTLEBELL', 'BEGINNER', 'COMPOUND', 'Stand upright holding a kettlebell in each hand at your sides.', '["Stand upright holding a kettlebell in each hand at your sides.","Brace your core and maintain an upright posture with shoulders back.","Lift one knee upward to hip height in a controlled marching motion.","Lower that foot to the floor and immediately lift the opposite knee.","Continue alternating legs in a slow, deliberate march for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0070', '/media/exercises/0070.mp4', NULL, 'f8530ebad427d89fd8b2f368522a67c83a4749add1aa1fa319adc7a0f880464f', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0070.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Kettlebell Hold March');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Lift Up', 'QUADS', 'GLUTES,LOWER BACK,SHOULDERS', 'KETTLEBELL', 'BEGINNER', 'COMPOUND', 'Stand with feet hip-width apart and a kettlebell on the floor between your feet.', '["Stand with feet hip-width apart and a kettlebell on the floor between your feet.","Hinge at the hips and bend your knees to grip the kettlebell handle with both hands.","Brace your core and maintain a flat back as you prepare to lift.","Drive through your heels and extend your hips and knees to stand upright, lifting the kettlebell.","Lower the kettlebell back to the floor in a controlled manner and repeat."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0071', '/media/exercises/0071.mp4', NULL, '071e47ec9cb04684c158f90c7972a32c4fff3d682dfae08ba774a10b0a1f9b51', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0071.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Kettlebell Lift Up');
UPDATE exercises SET media_url = '/media/exercises/0071.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Kettlebell Deadlift');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Swing', 'GLUTES', 'UPPER LEGS,LOWER BACK,SHOULDERS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with feet slightly wider than shoulder-width and the kettlebell on the floor in front of you.', '["Stand with feet slightly wider than shoulder-width and the kettlebell on the floor in front of you.","Hinge at the hips to grip the kettlebell with both hands and hike it back between your legs.","Explosively drive your hips forward to propel the kettlebell upward to chest or shoulder height.","Allow the kettlebell to swing back down and hike it back between your legs, hinging at the hips.","Repeat the swing in a fluid, continuous motion for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0072', '/media/exercises/0072.mp4', NULL, 'ddccdcbec89f3acadb8ee4cf82e022840778655164a2a465ffddef7325f973c4', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0072.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Kettlebell Swing');
UPDATE exercises SET media_url = '/media/exercises/0072.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('One-Arm Kettlebell Swing');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Leg Extension Machine', 'QUADS', '', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Sit on the leg extension machine and adjust the back pad so your knees align with the machine''s pivot point.', '["Sit on the leg extension machine and adjust the back pad so your knees align with the machine''s pivot point.","Place your shins behind the padded lever and grip the handles at your sides.","Extend your legs upward by straightening your knees until your legs are parallel to the floor.","Pause at the top and squeeze your quadriceps.","Slowly lower the lever back to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0073', '/media/exercises/0073.mp4', NULL, '0cc245b283d5813197a47fc01596784d67aa70c097af7297c1968935bf7e51e6', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0073.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Leg Extension Machine');
UPDATE exercises SET media_url = '/media/exercises/0073.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Leg Extensions');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Leg Press Machine', 'QUADS', 'GLUTES,UPPER LEGS', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Sit on the leg press machine and place your feet shoulder-width apart on the platform.', '["Sit on the leg press machine and place your feet shoulder-width apart on the platform.","Release the safety handles and lower the platform by bending your knees toward your chest.","Stop when your knees reach approximately 90 degrees or your lower back begins to lift off the seat.","Drive through your heels to extend your knees and push the platform back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0074', '/media/exercises/0074.mp4', NULL, '58267f0fb6d89f0381f1838861ab41e0458e4920bfd5b6175671be370b060c30', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0074.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('45-Degree Leg Press');
