MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lying Leg Curl Machine', 'QUADS', 'LOWER LEGS,GLUTES', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Lie face down on the leg curl machine and position the pad just above your heels.', '["Lie face down on the leg curl machine and position the pad just above your heels.","Grip the handles beneath the bench for stability.","Curl your heels toward your glutes by bending your knees as far as the machine allows.","Pause at the top and squeeze your hamstrings.","Slowly lower your legs back to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0075', '/media/exercises/0075.mp4', NULL, 'd1e3126d6a0034b7f56b5a45b375763db49133a0d3df005b5b231eebc5b526de', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0075.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Lying Leg Curl Machine');
UPDATE exercises SET media_url = '/media/exercises/0075.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Lying Leg Curls');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Rope Wave', 'SHOULDERS', 'UPPER ARMS,ABS,UPPER LEGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hold one end of a battle rope in each hand and stand in a half-squat position.', '["Hold one end of a battle rope in each hand and stand in a half-squat position.","Brace your core and keep your feet shoulder-width apart.","Rapidly raise and lower one arm while the other arm descends, creating alternating waves in the rope.","Maintain a continuous, powerful wave motion for the desired interval duration.","Rest and repeat for the desired number of sets."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0076', '/media/exercises/0076.mp4', NULL, '33e06e288881e7d74663bfbd269523077b25e89426a1ed759173100d999be7a0', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0076.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Battling Ropes');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Rowing Machine', 'BACK', 'UPPER LEGS,SHOULDERS,ABS', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Sit on the rowing machine, secure your feet in the straps, and grip the handle with both hands.', '["Sit on the rowing machine, secure your feet in the straps, and grip the handle with both hands.","Begin with your knees bent, leaning slightly forward, and arms extended.","Drive through your legs to extend your knees while simultaneously leaning back slightly.","As your legs reach full extension, pull the handle toward your lower chest by bending your elbows.","Reverse the sequence to return to the starting position and repeat for the desired duration."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0077', '/media/exercises/0077.mp4', NULL, 'c210d9eca171243063705b5a8e3e28cdcfe034069a4b1ca760ac22bcd358fdfe', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0077.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Rowing, Stationary');
UPDATE exercises SET media_url = '/media/exercises/0077.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Rowing Machine');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Run On Treadmill', 'CARDIO', 'UPPER LEGS,LOWER LEGS,GLUTES', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Step onto the treadmill and set your desired speed and incline level.', '["Step onto the treadmill and set your desired speed and incline level.","Begin walking and gradually increase the speed to your running pace.","Maintain an upright posture with a slight forward lean and land softly on your midfoot.","Swing your arms in coordination with your legs to maintain rhythm.","Continue running for the desired duration, then gradually decrease speed to a walking cool down."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0078', '/media/exercises/0078.mp4', NULL, 'ff3cddd7db8c512294e8d0e96ce5e053dce4a52a14d706fa7de5ff24cca0f0a7', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0078.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Run on Treadmill');
UPDATE exercises SET media_url = '/media/exercises/0078.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Running, Treadmill');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Seated Leg Curl Machine', 'QUADS', 'LOWER LEGS,GLUTES', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Sit on the seated leg curl machine and adjust the back pad so your knees align with the pivot point.', '["Sit on the seated leg curl machine and adjust the back pad so your knees align with the pivot point.","Place your legs over the top pad and secure the lower pad just above your ankles.","Curl your legs downward by bending your knees as far as the machine allows.","Pause at the bottom and squeeze your hamstrings.","Slowly return your legs to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0079', '/media/exercises/0079.mp4', NULL, '0146817fc4565eed20dc2b3edc9768e4c144e39234400d57c0cbd259443c9da3', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0079.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Seated Leg Curl Machine');
UPDATE exercises SET media_url = '/media/exercises/0079.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Seated Leg Curl');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Seated Overhead Press', 'SHOULDERS', 'TRICEPS,TRAPS', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Sit on a shoulder press machine and adjust the seat so the handles are at shoulder height.', '["Sit on a shoulder press machine and adjust the seat so the handles are at shoulder height.","Grip the handles with both hands and plant your feet flat on the floor.","Press the handles upward until your arms are fully extended overhead.","Pause briefly at the top, then slowly lower the handles back to shoulder height.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0080', '/media/exercises/0080.mp4', NULL, 'dc7dbac3377c469579dc6b22050682e1ef4f353293221c917527616d60a04de8', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0080.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Machine Shoulder Press');
UPDATE exercises SET media_url = '/media/exercises/0080.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Seated Overhead Press');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Step-Ups (Weighted)', 'QUADS', 'GLUTES,UPPER LEGS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand in front of a box or bench holding a dumbbell in each hand at your sides.', '["Stand in front of a box or bench holding a dumbbell in each hand at your sides.","Step one foot up onto the surface and drive through that heel to lift your body up.","Bring your back foot up to stand fully on the box.","Step the leading foot back down to the floor followed by the trailing foot.","Alternate the leading leg or complete all repetitions on one side before switching."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0081', '/media/exercises/0081.mp4', NULL, 'e4fbc371a7f43f10230c8e89c682f02b2c8180d2cf71b01c93b50b67e1ebd4d1', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0081.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Dumbbell Step Ups');
UPDATE exercises SET media_url = '/media/exercises/0081.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Barbell Step Ups');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Stepmill Machine Version 1', 'CARDIO', 'GLUTES,LOWER LEGS,UPPER LEGS', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Step onto the stepmill machine and grip the handrails lightly for balance.', '["Step onto the stepmill machine and grip the handrails lightly for balance.","Set your desired speed on the control panel.","Begin stepping at a comfortable pace, placing your full foot on each step.","Drive through your heel with each step to engage your glutes and quads.","Continue for the desired duration, maintaining an upright posture and minimizing reliance on the handrails."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0082', '/media/exercises/0082.mp4', NULL, 'fee95dadb5aaff82a4a4581eba9dbf5835ee0be8611f36a1a0a2c58bd8ec9e3b', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0082.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Step Mill');
UPDATE exercises SET media_url = '/media/exercises/0082.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Stairmaster');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Stepmill Machine', 'CARDIO', 'GLUTES,LOWER LEGS,UPPER LEGS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Mount the stepmill and set your target speed and duration.', '["Mount the stepmill and set your target speed and duration.","Step onto the rotating staircase and begin climbing at a steady pace.","Keep your torso upright and engage your core throughout the exercise.","Drive through each step using your full foot to activate the glutes and quads.","Complete the session for the desired duration, then slow down to cool off before dismounting."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0083', '/media/exercises/0083.mp4', NULL, '64bde093c0435ea0354769e3cf241d871c6e16c5209e214459b12fbcbbb61616', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0083.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Stepmill Machine');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Stiff-Legged Deadlift Machine', 'QUADS', 'GLUTES,LOWER BACK', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Stand on the platform of a deadlift machine with feet hip-width apart and grip the handles.', '["Stand on the platform of a deadlift machine with feet hip-width apart and grip the handles.","Keep your legs nearly straight with a slight bend in your knees.","Hinge at the hips and lower the handles along your legs until you feel a deep hamstring stretch.","Drive your hips forward to return to the upright starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0084', '/media/exercises/0084.mp4', NULL, '022e20f0d1e335a27b89342a2baa56f033c83b0aaf4bd702a329170eeef6cca1', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0084.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Smith Machine Stiff-Legged Deadlift');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Triceps Pushdown (Cable - Rope)', 'TRICEPS', 'LOWER ARMS', 'CABLE', 'BEGINNER', 'COMPOUND', 'Attach a rope handle to the high pulley of a cable machine and stand facing the machine.', '["Attach a rope handle to the high pulley of a cable machine and stand facing the machine.","Grasp the rope with both hands using a neutral grip and tuck your elbows close to your sides.","Push the rope downward by extending your arms until they are fully straight.","At the bottom, spread the rope ends apart slightly to maximize tricep contraction.","Slowly allow the rope to rise back to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0085', '/media/exercises/0085.mp4', NULL, '32fe2b643c4ee2281cf1afae4ed9e6a1a4a610d19f1298bda3f0a2b904ad8e99', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0085.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Triceps Pushdown');
UPDATE exercises SET media_url = '/media/exercises/0085.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Triceps Pushdown - Rope Attachment');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Walk On Treadmill', 'CARDIO', 'UPPER LEGS,LOWER LEGS,GLUTES', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Step onto the treadmill and set a comfortable walking speed and incline.', '["Step onto the treadmill and set a comfortable walking speed and incline.","Begin walking at your chosen pace, maintaining an upright posture.","Swing your arms naturally in coordination with your stride.","Keep your gaze forward and avoid looking down at your feet.","Continue walking for the desired duration, then gradually bring the belt to a stop."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0086', '/media/exercises/0086.mp4', NULL, 'fc92fd6a65f1402b247b3d17c37b71e344f82a7d9ebc134fb328db36999d5319', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0086.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Walk on Treadmill');
UPDATE exercises SET media_url = '/media/exercises/0086.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Walking, Treadmill');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Arnold Press Dumbbell', 'SHOULDERS', 'TRICEPS,TRAPS,UPPER ARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with back support and hold a dumbbell in each hand at chest height, palms facing you.', '["Sit on a bench with back support and hold a dumbbell in each hand at chest height, palms facing you.","Begin the press by rotating your palms to face forward as you push the dumbbells upward.","Continue pressing until your arms are fully extended overhead.","Reverse the motion, rotating your palms back to face you as you lower the dumbbells to chest height.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0087', '/media/exercises/0087.mp4', NULL, 'd93d119c165a13021a121a3ed6b78659956f75469adbdfb42998acd04ebd560d', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0087.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Arnold Dumbbell Press');
UPDATE exercises SET media_url = '/media/exercises/0087.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Arnold Press');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Overhead Press Standing', 'SHOULDERS', 'TRICEPS,TRAPS,ABS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with feet shoulder-width apart and hold a barbell at shoulder height with an overhand grip.', '["Stand with feet shoulder-width apart and hold a barbell at shoulder height with an overhand grip.","Brace your core and maintain a neutral spine throughout the movement.","Press the barbell directly overhead until your arms are fully extended.","Pause at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0088', '/media/exercises/0088.mp4', NULL, '2fa63f8f13ce9ca6481c1c4dac97eb38f3c0cd2da567ca4f0c549e60d324d3e0', 'licensed', 'video', 'verified', 'vital-catalog');
