UPDATE exercises SET media_url = '/media/exercises/0088.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Standing Military Press');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Upright Row', 'SHOULDERS', 'TRAPS,BICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand upright holding a barbell with an overhand grip, hands approximately shoulder-width apart.', '["Stand upright holding a barbell with an overhand grip, hands approximately shoulder-width apart.","Let the bar hang in front of your thighs with your arms extended.","Pull the bar upward along your body by raising your elbows above the level of your hands.","Continue pulling until the bar reaches chin height and your elbows are above your shoulders.","Slowly lower the bar back to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0089', '/media/exercises/0089.mp4', NULL, '5b39021ee07a4a3708c4a2ce61e2f67e22fddeb8ab675246dd111f2b409be47e', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0089.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Upright Barbell Row');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Overhead Standard', 'SHOULDERS', 'TRICEPS,TRAPS', 'DUMBBELL', 'BEGINNER', 'COMPOUND', 'Stand with feet shoulder-width apart and hold a dumbbell in each hand at shoulder height, palms facing forward.', '["Stand with feet shoulder-width apart and hold a dumbbell in each hand at shoulder height, palms facing forward.","Brace your core and maintain an upright posture.","Press the dumbbells upward until your arms are fully extended overhead.","Pause briefly at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0090', '/media/exercises/0090.mp4', NULL, 'ae2ae37e883f1fa87b287736a1d38d8371d8729c2210e0eab261fa0acdd4fbe8', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0090.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Dumbbell Shoulder Press');
UPDATE exercises SET media_url = '/media/exercises/0090.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Seated Dumbbell Press');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Upright Row', 'SHOULDERS', 'TRAPS,BICEPS', 'DUMBBELL', 'BEGINNER', 'COMPOUND', 'Stand upright holding a dumbbell in each hand with a neutral grip in front of your thighs.', '["Stand upright holding a dumbbell in each hand with a neutral grip in front of your thighs.","Pull the dumbbells upward along your body by raising your elbows above the level of your hands.","Continue pulling until the dumbbells reach chest height and your elbows are at shoulder level.","Pause at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0091', '/media/exercises/0091.mp4', NULL, 'c8b3f72863e9ee5e20d88baa751f17d134dbe4af0fadcb749d09db86e86f5bc9', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0091.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Standing Dumbbell Upright Row');
UPDATE exercises SET media_url = '/media/exercises/0091.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Dumbbell Upright Row');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Front Raise (Dumbbell)', 'SHOULDERS', 'CHEST,TRAPS', 'DUMBBELL', 'BEGINNER', 'COMPOUND', 'Stand upright holding a dumbbell in each hand in front of your thighs with palms facing your body.', '["Stand upright holding a dumbbell in each hand in front of your thighs with palms facing your body.","Keep a slight bend in your elbows and your back straight.","Raise one or both dumbbells forward and upward until your arms are parallel to the floor.","Pause briefly at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0092', '/media/exercises/0092.mp4', NULL, 'd32eeadcf42222b70244cec6d7c147f95fd308563504589d7880b1eab3e6aafb', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0092.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Front Dumbbell Raise');
UPDATE exercises SET media_url = '/media/exercises/0092.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Front Raise');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Front Raise (Weighted Plate)', 'SHOULDERS', 'CHEST,TRAPS', 'BODYWEIGHT', 'BEGINNER', 'COMPOUND', 'Stand upright and hold a weight plate with both hands at the 3 and 9 o''clock positions in front of your thighs.', '["Stand upright and hold a weight plate with both hands at the 3 and 9 o''clock positions in front of your thighs.","Keep a slight bend in your elbows and your core engaged.","Raise the plate forward and upward in a controlled arc until your arms are parallel to the floor.","Pause briefly at the top, then slowly lower the plate back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0093', '/media/exercises/0093.mp4', NULL, 'b51841c85b89cd990db4a9b3a250206fcbfe5fc3e1d14955855130b6a6e090a5', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0093.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Front Plate Raise');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Overhead Press', 'SHOULDERS', 'TRICEPS,TRAPS,ABS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with feet shoulder-width apart and hold a kettlebell in one hand at shoulder height in the rack position.', '["Stand with feet shoulder-width apart and hold a kettlebell in one hand at shoulder height in the rack position.","Brace your core and keep your elbow pointing forward.","Press the kettlebell straight overhead until your arm is fully extended.","Pause at the top, then slowly lower the kettlebell back to the rack position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0094', '/media/exercises/0094.mp4', NULL, '8a9fc6e7f5d9b848004b820266519393e5b9bcb434e68e17b7bec42554387143', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0094.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Alternating Kettlebell Press');
UPDATE exercises SET media_url = '/media/exercises/0094.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('One-Arm Kettlebell Military Press To The Side');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Cross Lateral Raise', 'SHOULDERS', 'SUPRASPINATUS,UPPER TRAPS', 'CABLE', 'BEGINNER', 'COMPOUND', 'Stand between two low cable pulleys and grasp the opposite handle with each hand so the cables cross in front of your body.', '["Stand between two low cable pulleys and grasp the opposite handle with each hand so the cables cross in front of your body.","Stand upright with your feet shoulder-width apart, keep your core braced, and maintain a slight bend in your elbows.","Raise both arms out to your sides until they are approximately parallel to the floor.","Pause briefly at the top while squeezing your lateral deltoids.","Slowly lower the handles back to the starting position under control and repeat."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0095', '/media/exercises/0095.mp4', NULL, 'a3355d00de4afb1db92b0f1ebede7336e8f652d1d157f9ecdb4ad4ac348c4af7', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0095.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Cable Seated Lateral Raise');
UPDATE exercises SET media_url = '/media/exercises/0095.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Cable Cross Lateral Raise');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lateral Raises (Dumbbell)', 'SHOULDERS', 'TRAPS', 'DUMBBELL', 'BEGINNER', 'COMPOUND', 'Stand upright holding a dumbbell in each hand at your sides with a neutral grip.', '["Stand upright holding a dumbbell in each hand at your sides with a neutral grip.","Keep a slight bend in your elbows and your core engaged.","Raise both dumbbells out to the sides in a wide arc until your arms are parallel to the floor.","Pause briefly at the top and squeeze your medial delts.","Slowly lower the dumbbells back to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0096', '/media/exercises/0096.mp4', NULL, 'c304cad8bcb05c345e4fd82d236e83d2f398c33386a6357f1513d608794e910b', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0096.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Side Lateral Raise');
UPDATE exercises SET media_url = '/media/exercises/0096.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Dumbbell Lateral Raise');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lateral Raise Machine', 'SHOULDERS', 'UPPER TRAPS,SUPRASPINATUS', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Stand on the platform of the lateral raise machine and position your upper arms against the pads.', '["Stand on the platform of the lateral raise machine and position your upper arms against the pads.","Keep your chest up, core engaged, and maintain a slight bend in your elbows.","Raise the pads outward by abducting your shoulders until your upper arms are approximately parallel to the floor.","Pause briefly at the top and squeeze your lateral deltoids.","Slowly lower the weight back to the starting position under control and repeat."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0097', '/media/exercises/0097.mp4', NULL, 'ea4dfd8e1c59099b8523be0ac2d10c9e6077e39c29808c066668c6f1162a8f26', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0097.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Machine Lateral Raise');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Military Press (Seated - Smith Machine)', 'SHOULDERS', 'TRICEPS,TRAPS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Set a bench inside a smith machine and adjust the bar to shoulder height.', '["Set a bench inside a smith machine and adjust the bar to shoulder height.","Sit on the bench and grip the bar with an overhand grip slightly wider than shoulder-width.","Unrack the bar and hold it at the front of your shoulders.","Press the bar upward until your arms are fully extended overhead.","Slowly lower the bar back to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0098', '/media/exercises/0098.mp4', NULL, '85ec0dda2d8d2862a0cd71b0526469c1bc4f8942d9df603e3e2e289fc9714468', 'licensed', 'video', 'verified', 'vital-catalog');
