MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Rear Delt Fly (Reverse Pec Deck)', 'SHOULDERS', 'RHOMBOIDS,TRAPS', 'MACHINE', 'BEGINNER', 'COMPOUND', 'Sit facing the pec deck machine and adjust the seat so your arms are parallel to the floor.', '["Sit facing the pec deck machine and adjust the seat so your arms are parallel to the floor.","Grip the handles with a neutral grip and keep a slight bend in your elbows.","Pull the handles outward and backward in a wide arcing motion by squeezing your rear delts and shoulder blades together.","Pause at the peak of the contraction.","Slowly return the handles to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0099', '/media/exercises/0099.mp4', NULL, '1a7905408368b0a4fbdf040e51857d73f57599553fa0cd043d6d6ca976b46f3a', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0099.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Rear Delt Machine (Reverse Pec Deck)');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Rear Delt Cable Fly', 'SHOULDERS', 'RHOMBOIDS,MIDDLE TRAPS', 'CABLE', 'BEGINNER', 'COMPOUND', 'Stand between two cable pulleys set at shoulder height.', '["Stand between two cable pulleys set at shoulder height.","Grasp the opposite cable handle with each hand and step back until there is tension on the cables.","Maintain a slight bend in your elbows and keep your chest up throughout the movement.","Pull your arms outward and backward in a wide arc until they are in line with your shoulders.","Squeeze your rear delts and upper back at the end of the movement.","Slowly return to the starting position under control and repeat."]', '["Rushing repetitions and losing eccentric cadence control.","Failing to maintain proper core bracing and spinal alignment."]', 3, '8-12', false, 'VitalAnimations 3D Biomechanical Engine', 'vital-animations', 'vital_0100', '/media/exercises/0100.mp4', NULL, 'c696d59e0b7251366e358590928b7bd96193c25514b1b04d43d1a3f1f24d0420', 'licensed', 'video', 'verified', 'vital-catalog');
UPDATE exercises SET media_url = '/media/exercises/0100.mp4', media_provider = 'licensed', media_type = 'video', review_status = 'verified', attribution = 'VitalAnimations 3D Biomechanical Engine' WHERE LOWER(name) = LOWER('Cable Rear Delt Fly');